import React, { useMemo } from 'react';
import dynamic from 'next/dynamic';
import { ResizerBoxProps } from './types';
import { ResizeWrapper } from './styles';

const ResizePanel = dynamic(
  () => import('components/shared/ResizePanel/ResizePanel'),
  { ssr: false }
);

const BoxMaxWidth = 518;
const BoxMinWidth = 250;

const ResizePanelDirection = {
  left: 'w',
  right: 'e',
}

const ResizerBox: React.FC<ResizerBoxProps> = ({
  expanded,
  initialWidth,
  children,
  saveDetailSize,
  direction,
  contentClassName,
}) => {
  const width = useMemo(() => {
    if (initialWidth > BoxMaxWidth) return BoxMaxWidth;
    if (initialWidth > BoxMinWidth) return BoxMinWidth;
    return initialWidth;
  }, [initialWidth]);

  return (
    <ResizeWrapper expanded={expanded}>
      <ResizePanel
        direction={ResizePanelDirection[direction || 'right']}
        handleClass="resize-handle"
        containerClass="resize-panel-container"
        borderClass="resize-border"
        contentClass={contentClassName}
        initialWidth={width}
        saveDetailSize={saveDetailSize}
      >
        {children}
      </ResizePanel>
    </ResizeWrapper>
  );
};

export default ResizerBox;
